//go:build closeout_l2_e35_r1

package nornicdb_test

// E35-R1 (light form): a vector write sent as soon as a restarted database
// answers, while the search service builds its indexes, must not wait for
// that build (the large-store run: the write's request was still waiting,
// after its commit, in refreshSearchAfterCommit -> ... ->
// search.(*Service).readLockOrQueue -> RWMutex.RLock).
//
// The store is generated by the test (60,000 Searchable nodes with 60-word
// texts and 64-value vectors, a fulltext and a declared vector index), not
// the 1.1 M-node store of an older build. The restart is a Close and Open of
// the same directory (index persistence off, so the start-up build runs).
// Two runtime settings are run: the plain process (no soft memory limit),
// and the server's soft memory limit (ApplyRuntimeMemory sets the cgroup-
// derived limit in a server) at the live heap, which is where a large store
// leaves it; with no headroom the search service's build-write queue cannot
// hold the write (pkg/search/build_write_queue.go: queueBuildWrite ->
// fitsLocked), and readLockOrQueue then waits for buildMu.

import (
	"context"
	"fmt"
	"math/rand"
	"path/filepath"
	"runtime"
	"runtime/debug"
	"sort"
	"strings"
	"testing"
	"time"

	"github.com/orneryd/nornicdb/pkg/nornicdb"
	"github.com/orneryd/nornicdb/pkg/search"
)

const (
	l2E35R1Nodes     = 60000
	l2E35R1Batch     = 2000
	l2E35R1Dims      = 64
	l2E35R1TextWords = 60
	// The write counts as waiting for the build when it took at least
	// l2E35R1WaitThreshold and returned only once the build had ended (or
	// not at all within the client timeout). The entry's 12,000-node control
	// returned in 120-162 ms during a build, so 2 s is a wide margin.
	l2E35R1WaitThreshold = 2 * time.Second
	l2E35R1WriteTimeout  = 4 * time.Minute
)

var l2E35R1Words = strings.Fields(`company registration office record invoice payment contract tenant lease insurance claim policy
letter statement balance account bank transfer receipt tax return pension salary employer notice council water energy
gas electricity mortgage loan interest rate quarter annual report audit director share dividend property survey
planning permission builder warranty guarantee repair boiler heating window roof garden fence neighbour dispute solicitor
court hearing judgment appeal deadline reminder overdue penalty refund credit debit card mobile phone broadband
subscription renewal cancellation vehicle registration licence insurance service garage mot inspection doctor hospital
appointment prescription dentist school college university tuition grant scholarship passport visa travel booking hotel
flight ticket parcel delivery courier customs import export supplier customer order quote estimate schedule meeting
minutes agenda board trustee charity donation membership club volunteer election vote census survey questionnaire
application form signature witness deed trust estate probate will executor beneficiary inheritance valuation`)

func l2E35R1Vector(r *rand.Rand) []float64 {
	v := make([]float64, l2E35R1Dims)
	for i := range v {
		v[i] = float64(int(r.Float64()*10000)) / 10000
	}
	return v
}

func l2E35R1Text(r *rand.Rand, n int) string {
	parts := make([]string, n)
	for i := range parts {
		parts[i] = l2E35R1Words[r.Intn(len(l2E35R1Words))]
	}
	return strings.Join(parts, " ")
}

func l2E35R1Config() *nornicdb.Config {
	c := nornicdb.DefaultConfig()
	c.Database.AsyncWritesEnabled = false
	c.Database.WALAutoCompactionEnabled = false
	c.Database.PersistSearchIndexes = false
	c.Memory.DecayEnabled = false
	c.Memory.EmbeddingEnabled = false
	c.Memory.AutoLinksEnabled = false
	c.Memory.EmbeddingDimensions = l2E35R1Dims
	return c
}

func l2E35R1Env(t *testing.T) {
	t.Setenv("NORNICDB_GPU_BACKEND", "cpu")
	t.Setenv("NORNICDB_HNSW_BUILD_GPU_ENABLED", "false")
	t.Setenv("NORNICDB_EMBEDDING_ENABLED", "false")
	t.Setenv("NORNICDB_AUTO_LINKS_ENABLED", "false")
	t.Setenv("NORNICDB_DECAY_ENABLED", "false")
}

// l2E35R1Seed writes the store and closes it.
func l2E35R1Seed(t *testing.T, dir string) {
	t.Helper()
	ctx := context.Background()
	db, err := nornicdb.Open(dir, l2E35R1Config())
	if err != nil {
		t.Fatalf("seed Open: %v", err)
	}
	for _, q := range []string{
		"CREATE FULLTEXT INDEX doc_text IF NOT EXISTS FOR (n:Searchable) ON EACH [n.text]",
		"CREATE VECTOR INDEX doc_vec IF NOT EXISTS FOR (n:Searchable) ON (n.embedding) OPTIONS {indexConfig: {`vector.dimensions`: 64, `vector.similarity_function`: 'cosine'}}",
		"CREATE INDEX searchable_id IF NOT EXISTS FOR (s:Searchable) ON (s.id)",
	} {
		if _, err := db.ExecuteCypher(ctx, q, nil); err != nil {
			_ = db.Close()
			t.Fatalf("seed schema %q: %v", q, err)
		}
	}
	r := rand.New(rand.NewSource(11))
	for start := 0; start < l2E35R1Nodes; start += l2E35R1Batch {
		rows := make([]any, 0, l2E35R1Batch)
		for i := start; i < start+l2E35R1Batch && i < l2E35R1Nodes; i++ {
			text := l2E35R1Text(r, l2E35R1TextWords) // the text is drawn before the vector
			rows = append(rows, map[string]any{"id": fmt.Sprintf("s%d", i), "text": text, "e": l2E35R1Vector(r)})
		}
		if _, err := db.ExecuteCypher(ctx, "UNWIND $rows AS r CREATE (s:Searchable {id: r.id, text: r.text, current: true, embedding: r.e})", map[string]any{"rows": rows}); err != nil {
			_ = db.Close()
			t.Fatalf("seed rows from %d: %v", start, err)
		}
	}
	if err := db.Close(); err != nil {
		t.Fatalf("seed Close: %v", err)
	}
}

type l2E35R1Outcome struct {
	variant         string
	sawBuilding     bool
	writeLatency    time.Duration
	writeErr        error
	writeTimedOut   bool
	writeSentToDone time.Duration // write sent -> build done
	buildEndedFirst bool          // the build ended before the write returned
	duringSearches  []time.Duration
	afterSearches   []time.Duration
	found           any
	stackRefresh    bool // a goroutine was in readLockOrQueue while the write was in flight
	stackMVCCFloor  bool // a goroutine was in recoverNamespaceMVCCFloor while the write was in flight
	stackSample     string
}

func l2E35R1Median(ds []time.Duration) time.Duration {
	if len(ds) == 0 {
		return 0
	}
	c := append([]time.Duration(nil), ds...)
	sort.Slice(c, func(i, j int) bool { return c[i] < c[j] })
	return c[len(c)/2]
}

func (o l2E35R1Outcome) String() string {
	return fmt.Sprintf("variant=%s saw_building=%v write_latency=%v write_err=%v write_timed_out=%v build_done_after_send=%v build_ended_before_write_returned=%v searches_during_build=%d median=%v searches_after=%v found_after=%v stack_readLockOrQueue=%v stack_recoverNamespaceMVCCFloor=%v",
		o.variant, o.sawBuilding, o.writeLatency, o.writeErr, o.writeTimedOut, o.writeSentToDone, o.buildEndedFirst, len(o.duringSearches), l2E35R1Median(o.duringSearches), o.afterSearches, o.found, o.stackRefresh, o.stackMVCCFloor)
}

// l2E35R1Restart opens the stopped store, waits until the start-up build is
// seen running, sends the write at once, times vector searches until the
// build is done and three after it, and samples goroutine stacks while the
// write is in flight.
func l2E35R1Restart(t *testing.T, dir, variant string, softLimit bool) l2E35R1Outcome {
	t.Helper()
	ctx := context.Background()
	out := l2E35R1Outcome{variant: variant}
	if softLimit {
		prev := debug.SetMemoryLimit(-1)
		runtime.GC()
		var ms runtime.MemStats
		runtime.ReadMemStats(&ms)
		debug.SetMemoryLimit(int64(ms.HeapAlloc))
		defer debug.SetMemoryLimit(prev)
	}
	db, err := nornicdb.Open(dir, l2E35R1Config())
	if err != nil {
		t.Fatalf("%s: Open: %v", variant, err)
	}
	defer func() { _ = db.Close() }()
	if _, err := db.ExecuteCypher(ctx, "RETURN 1 AS one", nil); err != nil {
		t.Fatalf("%s: RETURN 1: %v", variant, err)
	}
	svc, err := db.GetOrCreateSearchService("nornic", db.GetStorage())
	if err != nil {
		t.Fatalf("%s: GetOrCreateSearchService: %v", variant, err)
	}
	deadline := time.Now().Add(60 * time.Second)
	for time.Now().Before(deadline) {
		if svc.BuildInProgress() {
			out.sawBuilding = true
			break
		}
		if svc.IsReady() {
			break
		}
		time.Sleep(2 * time.Millisecond)
	}

	r := rand.New(rand.NewSource(7))
	writeVec := l2E35R1Vector(r)
	type writeResult struct {
		err     error
		elapsed time.Duration
		at      time.Time
	}
	writeDone := make(chan writeResult, 1)
	sent := time.Now()
	go func() {
		wctx, cancel := context.WithTimeout(ctx, l2E35R1WriteTimeout)
		defer cancel()
		start := time.Now()
		_, err := db.ExecuteCypher(wctx, "CREATE (:Searchable {id: 'during-build', text: 'newly written', embedding: $v})", map[string]any{"v": writeVec})
		writeDone <- writeResult{err: err, elapsed: time.Since(start), at: time.Now()}
	}()

	buildDone := make(chan time.Time, 1)
	go func() {
		for {
			if svc.IsReady() && !svc.BuildInProgress() {
				buildDone <- time.Now()
				return
			}
			if time.Since(sent) > l2E35R1WriteTimeout+time.Minute {
				close(buildDone)
				return
			}
			time.Sleep(10 * time.Millisecond)
		}
	}()

	sampleStacks := func() {
		buf := make([]byte, 16<<20)
		n := runtime.Stack(buf, true)
		s := string(buf[:n])
		if strings.Contains(s, "readLockOrQueue") {
			out.stackRefresh = true
			if out.stackSample == "" {
				for _, g := range strings.Split(s, "\n\n") {
					if strings.Contains(g, "readLockOrQueue") {
						out.stackSample = g
						break
					}
				}
			}
		}
		if strings.Contains(s, "recoverNamespaceMVCCFloor") {
			out.stackMVCCFloor = true
		}
	}

	var wr *writeResult
	var buildEnd time.Time
	buildEndKnown := false
	query := "CALL db.index.vector.queryNodes('doc_vec', 300, $v) YIELD node, score RETURN node.id AS id, score"
	lastSample := time.Now()
	bd := (<-chan time.Time)(buildDone)
	for wr == nil || !buildEndKnown {
		select {
		case res := <-writeDone:
			wr = &res
			continue
		case at, ok := <-bd:
			if ok {
				buildEnd = at
			}
			buildEndKnown = true
			bd = nil
			continue
		default:
		}
		if wr == nil && time.Since(lastSample) >= 500*time.Millisecond {
			sampleStacks()
			lastSample = time.Now()
		}
		if !buildEndKnown {
			qctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
			start := time.Now()
			_, qerr := db.ExecuteCypher(qctx, query, map[string]any{"v": l2E35R1Vector(r)})
			cancel()
			if qerr == nil {
				out.duringSearches = append(out.duringSearches, time.Since(start))
			}
		} else {
			time.Sleep(10 * time.Millisecond)
		}
	}
	out.writeErr, out.writeLatency = wr.err, wr.elapsed
	out.writeTimedOut = wr.err != nil && wr.elapsed >= l2E35R1WriteTimeout-time.Second
	if !buildEnd.IsZero() {
		out.writeSentToDone = buildEnd.Sub(sent)
		out.buildEndedFirst = !buildEnd.After(wr.at.Add(200 * time.Millisecond))
	}
	for i := 0; i < 3; i++ {
		start := time.Now()
		if _, err := db.ExecuteCypher(ctx, query, map[string]any{"v": l2E35R1Vector(r)}); err == nil {
			out.afterSearches = append(out.afterSearches, time.Since(start))
		}
	}
	if res, err := db.ExecuteCypher(ctx, "MATCH (n:Searchable {id: 'during-build'}) RETURN count(n)", nil); err == nil && len(res.Rows) > 0 && len(res.Rows[0]) > 0 {
		out.found = res.Rows[0][0]
	}
	return out
}

// l2E35R1Waited: the write waited for the build.
func l2E35R1Waited(o l2E35R1Outcome) bool {
	return o.writeTimedOut || (o.writeLatency >= l2E35R1WaitThreshold && o.buildEndedFirst)
}

func TestL2_e35_r1_Repro(t *testing.T) {
	l2E35R1Env(t)
	dir := filepath.Join(t.TempDir(), "data")
	l2E35R1Seed(t, dir)
	for _, v := range []struct {
		name      string
		softLimit bool
	}{{"plain-process", false}, {"soft-memory-limit-at-live-heap", true}} {
		o := l2E35R1Restart(t, dir, v.name, v.softLimit)
		if !o.sawBuilding || (o.writeSentToDone < l2E35R1WaitThreshold && !l2E35R1Waited(o)) {
			t.Logf("L2RESULT E35-R1 INCONCLUSIVE %s (the build window after the write was shorter than %v; scale the store up)", o, l2E35R1WaitThreshold)
			t.Errorf("%s: inconclusive: no build window of at least %v after the write was sent", v.name, l2E35R1WaitThreshold)
			continue
		}
		if l2E35R1Waited(o) {
			t.Logf("L2RESULT E35-R1 DEFECT %s", o)
			t.Errorf("%s: the vector write waited for the search build: %v (build done %v after the write was sent)", v.name, o.writeLatency, o.writeSentToDone)
			if o.stackSample != "" {
				t.Logf("stack of the waiting goroutine:\n%s", o.stackSample)
			}
			continue
		}
		t.Logf("L2RESULT E35-R1 OK %s", o)
	}
}

// Control: a write sent after the start-up build has finished returns in
// normal time and is stored.
func TestL2_e35_r1_Control(t *testing.T) {
	l2E35R1Env(t)
	ctx := context.Background()
	dir := filepath.Join(t.TempDir(), "data")
	l2E35R1Seed(t, dir)
	db, err := nornicdb.Open(dir, l2E35R1Config())
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	defer func() { _ = db.Close() }()
	if _, err := db.EnsureSearchIndexes(ctx, "nornic", nil, nornicdb.SearchIndexBuildWait); err != nil {
		t.Fatalf("EnsureSearchIndexes: %v", err)
	}
	var svc *search.Service
	if svc, err = db.GetOrCreateSearchService("nornic", db.GetStorage()); err != nil {
		t.Fatalf("GetOrCreateSearchService: %v", err)
	}
	deadline := time.Now().Add(5 * time.Minute)
	for !(svc.IsReady() && !svc.BuildInProgress()) && time.Now().Before(deadline) {
		time.Sleep(20 * time.Millisecond)
	}
	r := rand.New(rand.NewSource(7))
	start := time.Now()
	_, err = db.ExecuteCypher(ctx, "CREATE (:Searchable {id: 'after-build', text: 'newly written', embedding: $v})", map[string]any{"v": l2E35R1Vector(r)})
	elapsed := time.Since(start)
	res, cerr := db.ExecuteCypher(ctx, "MATCH (n:Searchable {id: 'after-build'}) RETURN count(n)", nil)
	var found any
	if cerr == nil && len(res.Rows) > 0 && len(res.Rows[0]) > 0 {
		found = res.Rows[0][0]
	}
	t.Logf("control: write after the build took %v (err %v), found=%v", elapsed, err, found)
	if err != nil || elapsed >= l2E35R1WaitThreshold || fmt.Sprint(found) != "1" {
		t.Errorf("control: want the write after the build under %v and stored once; got %v, err %v, found %v", l2E35R1WaitThreshold, elapsed, err, found)
	}
}

// Cause: the large-store dumps put the waiting write in
// search.(*Service).readLockOrQueue (pkg/search/build_write_queue.go) on
// buildMu's read lock, reached from the commit's search refresh. This runs
// the soft-limit variant and logs the stack of the goroutine found in
// readLockOrQueue while the write was in flight, and whether any goroutine
// was in recoverNamespaceMVCCFloor (the 20 s phase of the large store).
func TestL2_e35_r1_Cause(t *testing.T) {
	l2E35R1Env(t)
	dir := filepath.Join(t.TempDir(), "data")
	l2E35R1Seed(t, dir)
	o := l2E35R1Restart(t, dir, "soft-memory-limit-at-live-heap", true)
	t.Logf("CAUSE %s", o)
	if o.stackSample != "" {
		t.Logf("CAUSE stack in readLockOrQueue:\n%s", o.stackSample)
	} else {
		t.Logf("CAUSE no goroutine was seen in readLockOrQueue while the write was in flight")
	}
}
